import {
    detectPillPattern,
    parseSinglePill,
    mapPillPrefixToTsRoot,
    isUuidPrefix,
    createPropertyAccessFromPath,
    createTemplateExpressionFromPillString,
    convertPillStringToShape,
} from '../../../../build-plugins/src/flow/utils/pill-string-parser'
import type { Diagnostics } from '@servicenow/sdk-build-core'

// Mock diagnostics for testing
const createMockDiagnostics = (): Diagnostics => {
    const warnings: string[] = []
    const errors: string[] = []

    return {
        warn: (_source: any, message: string) => {
            warnings.push(message)
        },
        error: (_source: any, message: string) => {
            errors.push(message)
        },
        getWarnings: () => warnings,
        getErrors: () => errors,
    } as unknown as Diagnostics
}

// Mock source/record for testing
const mockSource = { type: 'mock-source' } as any
const mockDiagnostics = createMockDiagnostics()

describe('pill-string-parser', () => {
    describe('detectPillPattern', () => {
        it('detects simple pills', () => {
            expect(detectPillPattern('{{trigger.name}}')).toBe('simple')
            expect(detectPillPattern('  {{trigger.name}}  ')).toBe('simple')
            expect(detectPillPattern('{{flow_variable.array}}')).toBe('simple')
        })

        it('detects template pills', () => {
            expect(detectPillPattern('Hello {{trigger.name}}')).toBe('template')
            expect(detectPillPattern('{{trigger.name}} World')).toBe('template')
            expect(detectPillPattern('Lead {{trigger.name}} trail {{trigger.id}}')).toBe('template')
        })

        it('detects no pills', () => {
            expect(detectPillPattern('hello')).toBe('none')
            expect(detectPillPattern('just plain text')).toBe('none')
            expect(detectPillPattern('')).toBe('none')
            expect(detectPillPattern('{ not a pill }')).toBe('none')
        })

        it('handles edge cases', () => {
            expect(detectPillPattern(null as any)).toBe('none')
            expect(detectPillPattern(undefined as any)).toBe('none')
            expect(detectPillPattern(123 as any)).toBe('none')
        })
    })

    describe('parseSinglePill', () => {
        it('parses trigger pill', () => {
            const result = parseSinglePill('{{trigger.table_name}}')
            expect(result).toEqual({
                prefix: 'trigger',
                path: 'table_name',
                fullMatch: '{{trigger.table_name}}',
            })
        })

        it('parses flow_variable pill', () => {
            const result = parseSinglePill('{{flow_variable.myVar}}')
            expect(result).toEqual({
                prefix: 'flow_variable',
                path: 'myVar',
                fullMatch: '{{flow_variable.myVar}}',
            })
        })

        it('parses nested path', () => {
            const result = parseSinglePill('{{trigger.record.nested.value}}')
            expect(result).toEqual({
                prefix: 'trigger',
                path: 'record.nested.value',
                fullMatch: '{{trigger.record.nested.value}}',
            })
        })

        it('parses UUID-based pill', () => {
            const result = parseSinglePill('{{f56a03c1-18f6-4f7b-9c61-0d4ff472b334.output.name}}')
            expect(result).toEqual({
                prefix: 'f56a03c1-18f6-4f7b-9c61-0d4ff472b334',
                path: 'output.name',
                fullMatch: '{{f56a03c1-18f6-4f7b-9c61-0d4ff472b334.output.name}}',
            })
        })

        it('returns null for invalid format', () => {
            expect(parseSinglePill('{trigger}')).toBeNull()
            expect(parseSinglePill('{{trigger}}')).toBeNull() // No dot
            expect(parseSinglePill('{{.table_name}}')).toEqual({
                prefix: '',
                path: 'table_name',
                fullMatch: '{{.table_name}}',
            })
            expect(parseSinglePill('')).toBeNull()
        })

        it('handles whitespace', () => {
            const result = parseSinglePill('{{  trigger.table_name  }}')
            expect(result).toEqual({
                prefix: 'trigger',
                path: 'table_name',
                fullMatch: '{{  trigger.table_name  }}',
            })
        })
    })

    describe('mapPillPrefixToTsRoot', () => {
        it('maps semantic prefixes correctly', () => {
            expect(mapPillPrefixToTsRoot('trigger')).toBe('params.trigger')
            expect(mapPillPrefixToTsRoot('flow_variable')).toBe('params.flowVariables')
            expect(mapPillPrefixToTsRoot('inputs')).toBe('params.inputs')
            expect(mapPillPrefixToTsRoot('outputs')).toBe('params.outputs')
            expect(mapPillPrefixToTsRoot('subflow')).toBe('params.inputs')
        })

        it('returns null for unknown prefixes', () => {
            expect(mapPillPrefixToTsRoot('unknown')).toBeNull()
            expect(mapPillPrefixToTsRoot('action')).toBeNull()
            expect(mapPillPrefixToTsRoot('')).toBeNull()
        })

        it('returns null for UUID prefixes', () => {
            expect(mapPillPrefixToTsRoot('f56a03c1-18f6-4f7b-9c61-0d4ff472b334')).toBeNull()
        })
    })

    describe('isUuidPrefix', () => {
        it('detects valid UUIDs', () => {
            expect(isUuidPrefix('f56a03c1-18f6-4f7b-9c61-0d4ff472b334')).toBe(true)
            expect(isUuidPrefix('F56A03C1-18F6-4F7B-9C61-0D4FF472B334')).toBe(true)
            expect(isUuidPrefix('00000000-0000-0000-0000-000000000000')).toBe(true)
        })

        it('rejects invalid UUIDs', () => {
            expect(isUuidPrefix('trigger')).toBe(false)
            expect(isUuidPrefix('flow_variable')).toBe(false)
            expect(isUuidPrefix('f56a03c1-18f6-4f7b')).toBe(false) // Too short
            expect(isUuidPrefix('not-a-uuid-at-all-here')).toBe(false)
            expect(isUuidPrefix('')).toBe(false)
        })
    })

    describe('createPropertyAccessFromPath', () => {
        it('creates PropertyAccessShape for valid paths', () => {
            const shape = createPropertyAccessFromPath('params.trigger.name', mockSource)
            expect(shape).toBeDefined()
            expect(shape?.getElements()).toHaveLength(3)
        })

        it('creates PropertyAccessShape for nested paths', () => {
            const shape = createPropertyAccessFromPath('params.trigger.record.nested.value', mockSource)
            expect(shape).toBeDefined()
            expect(shape?.getElements()).toHaveLength(5)
        })

        it('returns null for invalid paths', () => {
            expect(createPropertyAccessFromPath('singlepart', mockSource)).toBeNull()
            expect(createPropertyAccessFromPath('', mockSource)).toBeNull()
        })
    })

    describe('createTemplateExpressionFromPillString', () => {
        it('creates template with single pill', () => {
            const template = createTemplateExpressionFromPillString('Hello {{trigger.name}}', mockSource)

            expect(template).toBeDefined()
            expect(template?.getLiteralText()).toBe('Hello ')
            expect(template?.getSpans()).toHaveLength(1)
        })

        it('creates template with multiple pills', () => {
            const template = createTemplateExpressionFromPillString(
                'Hello {{trigger.name}}, your ID is {{trigger.sys_id}}',
                mockSource
            )

            expect(template).toBeDefined()
            expect(template?.getLiteralText()).toBe('Hello ')
            expect(template?.getSpans()).toHaveLength(2)
        })

        it('creates template with leading text', () => {
            const template = createTemplateExpressionFromPillString(
                'Leadtext bla {{trigger.table_name}} trail text blah',
                mockSource
            )

            expect(template).toBeDefined()
            expect(template?.getLiteralText()).toBe('Leadtext bla ')
            expect(template?.getSpans()).toHaveLength(1)
        })

        it('creates template with trailing text', () => {
            const template = createTemplateExpressionFromPillString('{{trigger.name}} is your name', mockSource)

            expect(template).toBeDefined()
            expect(template?.getLiteralText()).toBe('')
            expect(template?.getSpans()).toHaveLength(1)
        })

        it('silently ignores UUID-based pills', () => {
            const template = createTemplateExpressionFromPillString(
                'Action: {{f56a03c1-18f6-4f7b-9c61-0d4ff472b334.output}}',
                mockSource
            )

            // UUID pills are silently ignored (Phase 3), template should be null
            expect(template).toBeNull()
        })

        it('silently ignores invalid pills', () => {
            const template = createTemplateExpressionFromPillString('Hello {{invalid}}', mockSource)

            // Invalid pills are silently ignored, template should be null (no valid pills found)
            expect(template).toBeNull()
        })

        it('returns null when no valid pills found', () => {
            const template = createTemplateExpressionFromPillString('No pills here', mockSource)

            expect(template).toBeNull()
        })
    })

    describe('convertPillStringToShape', () => {
        it('converts simple trigger pill to PropertyAccessShape', () => {
            const shape = convertPillStringToShape('{{trigger.table_name}}', mockSource, mockDiagnostics, 'param')

            expect(shape).toBeDefined()
            // Should be PropertyAccessShape
            expect(shape?.constructor.name).toBe('PropertyAccessShape')
        })

        it('converts simple flow_variable pill to PropertyAccessShape', () => {
            const shape = convertPillStringToShape('{{flow_variable.myVar}}', mockSource, mockDiagnostics, 'param')

            expect(shape).toBeDefined()
            expect(shape?.constructor.name).toBe('PropertyAccessShape')
        })

        it('converts template to TemplateExpressionShape', () => {
            const shape = convertPillStringToShape('Hello {{trigger.name}}', mockSource, mockDiagnostics, 'param')

            expect(shape).toBeDefined()
            expect(shape?.constructor.name).toBe('TemplateExpressionShape')
        })

        it('returns undefined for non-pill strings', () => {
            const shape = convertPillStringToShape('just text', mockSource, mockDiagnostics, 'param')

            expect(shape).toBeUndefined()
        })

        it('returns undefined for UUID pills (silently)', () => {
            const shape = convertPillStringToShape(
                '{{f56a03c1-18f6-4f7b-9c61-0d4ff472b334.output}}',
                mockSource,
                mockDiagnostics,
                'param'
            )

            // UUID pills silently return undefined to fall back to string literal
            expect(shape).toBeUndefined()
        })

        it('returns undefined for unknown prefixes (silently)', () => {
            const shape = convertPillStringToShape('{{unknown.path}}', mockSource, mockDiagnostics, 'param')

            // Unknown prefixes silently return undefined to fall back to normal value handling
            expect(shape).toBeUndefined()
        })

        it('returns undefined for invalid format (silently)', () => {
            const shape = convertPillStringToShape('{{invalid}}', mockSource, mockDiagnostics, 'param')

            // Invalid format silently returns undefined to fall back to normal value handling
            expect(shape).toBeUndefined()
        })
    })

    describe('Integration tests', () => {
        let diagnostics: Diagnostics

        beforeEach(() => {
            diagnostics = createMockDiagnostics()
        })

        it('handles real-world trigger pill example', () => {
            const input = '{{trigger.table_name}}'
            const shape = convertPillStringToShape(input, mockSource, diagnostics, 'param')

            expect(shape).toBeDefined()
            expect(shape?.constructor.name).toBe('PropertyAccessShape')

            // No warnings should be generated for valid pills
            const warnings = (diagnostics as any).getWarnings()
            expect(warnings.length).toBe(0)
        })

        it('handles real-world template example from pill-examples.now.ts', () => {
            const input = 'Leadtext bla {{trigger.table_name}} trail text blah'
            const shape = convertPillStringToShape(input, mockSource, diagnostics, 'param')

            expect(shape).toBeDefined()
            expect(shape?.constructor.name).toBe('TemplateExpressionShape')

            const warnings = (diagnostics as any).getWarnings()
            expect(warnings.length).toBe(0)
        })

        it('handles flow variable array reference', () => {
            const input = '{{flow_variable.array}}'
            const shape = convertPillStringToShape(input, mockSource, diagnostics, 'param')

            expect(shape).toBeDefined()
            expect(shape?.constructor.name).toBe('PropertyAccessShape')

            const warnings = (diagnostics as any).getWarnings()
            expect(warnings.length).toBe(0)
        })

        it('handles subflow inputs reference', () => {
            const input = '{{inputs.empName}}'
            const shape = convertPillStringToShape(input, mockSource, diagnostics, 'param')

            expect(shape).toBeDefined()
            expect(shape?.constructor.name).toBe('PropertyAccessShape')

            const warnings = (diagnostics as any).getWarnings()
            expect(warnings.length).toBe(0)
        })

        it('handles subflow prefix (maps to params.inputs)', () => {
            const input = '{{subflow.isEmployee}}'
            const shape = convertPillStringToShape(input, mockSource, diagnostics, 'param')

            expect(shape).toBeDefined()
            expect(shape?.constructor.name).toBe('PropertyAccessShape')

            const warnings = (diagnostics as any).getWarnings()
            expect(warnings.length).toBe(0)
        })

        it('handles subflow prefix in template', () => {
            const input = 'Hello {{subflow.empName}}'
            const shape = convertPillStringToShape(input, mockSource, diagnostics, 'param')

            expect(shape).toBeDefined()
            expect(shape?.constructor.name).toBe('TemplateExpressionShape')

            const warnings = (diagnostics as any).getWarnings()
            expect(warnings.length).toBe(0)
        })
    })
})
